const html = "<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>이성호 | 자기소개</title>\n  <script>\n    (() => {\n      try {\n        const saved = localStorage.getItem(\"profile-theme\");\n        const systemDark = window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\n        document.documentElement.dataset.theme = saved || (systemDark ? \"dark\" : \"light\");\n      } catch {\n        document.documentElement.dataset.theme = \"light\";\n      }\n    })();\n  </script>\n  <style>\n    :root {\n      --ink: #18212b;\n      --text: #4e5d6c;\n      --muted: #83909c;\n      --blue: #378fca;\n      --blue-soft: #e7f3fa;\n      --mint: #dff3ea;\n      --peach: #ffe9d9;\n      --paper: #ffffff;\n      --page: #f4f6f7;\n      --line: #dfe5e9;\n      color-scheme: light;\n    }\n\n    :root[data-theme=\"dark\"] {\n      --ink: #f1f6f9;\n      --text: #c2cdd4;\n      --muted: #8f9da7;\n      --blue: #62afe0;\n      --blue-soft: #17384b;\n      --mint: #193d35;\n      --peach: #4a3022;\n      --paper: #121a20;\n      --page: #0b1116;\n      --line: #29343c;\n      color-scheme: dark;\n    }\n\n    * {\n      box-sizing: border-box;\n    }\n\n    html {\n      scroll-behavior: smooth;\n    }\n\n    body {\n      margin: 0;\n      color: var(--text);\n      background: var(--page);\n      font-family: \"Malgun Gothic\", \"Apple SD Gothic Neo\", Arial, sans-serif;\n      line-height: 1.65;\n    }\n\n    .page {\n      position: relative;\n      width: min(1120px, calc(100% - 36px));\n      margin: 24px auto;\n      background: var(--paper);\n      box-shadow: 0 16px 50px rgba(24, 33, 43, 0.07);\n    }\n\n    .theme-toggle {\n      position: absolute;\n      top: 22px;\n      right: 24px;\n      z-index: 10;\n      display: inline-flex;\n      gap: 7px;\n      align-items: center;\n      padding: 8px 11px;\n      color: var(--text);\n      background: var(--paper);\n      border: 1px solid var(--line);\n      border-radius: 999px;\n      font: inherit;\n      font-size: 0.78rem;\n      font-weight: 700;\n      cursor: pointer;\n    }\n\n    .theme-toggle:hover {\n      color: var(--blue);\n      border-color: var(--blue);\n    }\n\n    .theme-toggle:focus-visible {\n      outline: 3px solid color-mix(in srgb, var(--blue) 35%, transparent);\n      outline-offset: 3px;\n    }\n\n    .theme-icon {\n      font-size: 0.95rem;\n      line-height: 1;\n    }\n\n    .hero {\n      min-height: 460px;\n      display: grid;\n      grid-template-columns: 1fr 280px;\n      gap: 50px;\n      align-items: center;\n      padding: clamp(42px, 7vw, 82px);\n      border-bottom: 1px solid var(--line);\n    }\n\n    p,\n    h1,\n    h2,\n    h3 {\n      margin-top: 0;\n    }\n\n    .hero-label {\n      margin-bottom: 15px;\n      color: var(--blue);\n      font-size: 0.82rem;\n      font-weight: 800;\n      letter-spacing: 0.16em;\n    }\n\n    h1 {\n      margin-bottom: 10px;\n      color: var(--ink);\n      font-size: clamp(4rem, 10vw, 7.5rem);\n      line-height: 0.94;\n      letter-spacing: -0.08em;\n    }\n\n    .name-en {\n      margin-bottom: 30px;\n      color: var(--muted);\n      font-size: 0.9rem;\n      font-weight: 700;\n      letter-spacing: 0.22em;\n    }\n\n    .job {\n      margin-bottom: 7px;\n      color: var(--ink);\n      font-size: clamp(1.05rem, 2.3vw, 1.35rem);\n      font-weight: 800;\n      word-break: keep-all;\n    }\n\n    .role {\n      margin-bottom: 20px;\n      color: var(--muted);\n      font-size: 0.94rem;\n    }\n\n    .hero-statement {\n      max-width: 610px;\n      margin-bottom: 0;\n      color: var(--ink);\n      font-size: clamp(1.2rem, 2.8vw, 1.75rem);\n      font-weight: 700;\n      line-height: 1.5;\n      word-break: keep-all;\n    }\n\n    .portrait {\n      width: 250px;\n      aspect-ratio: 1;\n      display: grid;\n      place-items: center;\n      position: relative;\n      overflow: hidden;\n      justify-self: end;\n      color: var(--paper);\n      background: var(--blue);\n      border-radius: 50%;\n    }\n\n    .portrait::before {\n      content: \"\";\n      position: absolute;\n      inset: 0;\n      background: repeating-linear-gradient(\n        125deg,\n        rgba(255,255,255,.13) 0 2px,\n        transparent 2px 12px\n      );\n    }\n\n    .portrait::after {\n      content: \"\";\n      position: absolute;\n      width: 135px;\n      height: 135px;\n      right: -38px;\n      bottom: -38px;\n      background: rgba(255,255,255,.12);\n      border-radius: 50%;\n    }\n\n    .initials {\n      z-index: 1;\n      font-size: 4.4rem;\n      font-weight: 900;\n      letter-spacing: -0.05em;\n    }\n\n    .plant {\n      position: absolute;\n      right: 18%;\n      bottom: 15%;\n      z-index: 2;\n      font-size: 2.2rem;\n    }\n\n    .content {\n      padding: 0 clamp(28px, 7vw, 82px);\n    }\n\n    .section {\n      display: grid;\n      grid-template-columns: minmax(190px, 28%) 1fr;\n      gap: clamp(30px, 6vw, 74px);\n      padding: clamp(34px, 5vw, 56px) 0;\n      border-bottom: 1px solid var(--line);\n    }\n\n    .section:last-child {\n      border-bottom: 0;\n    }\n\n    .section-index {\n      display: block;\n      margin-bottom: 8px;\n      color: var(--blue);\n      font-size: 0.76rem;\n      font-weight: 800;\n      letter-spacing: 0.12em;\n    }\n\n    h2 {\n      margin-bottom: 0;\n      color: var(--ink);\n      font-size: clamp(1.65rem, 3.4vw, 2.5rem);\n      line-height: 1.2;\n      letter-spacing: -0.05em;\n    }\n\n    .section-body {\n      align-self: center;\n    }\n\n    .lead {\n      max-width: 680px;\n      margin-bottom: 0;\n      color: var(--ink);\n      font-size: clamp(1.04rem, 2vw, 1.22rem);\n      font-weight: 700;\n      line-height: 1.75;\n      word-break: keep-all;\n    }\n\n    .sub-copy {\n      max-width: 680px;\n      margin: 12px 0 0;\n      color: var(--text);\n      font-size: 0.94rem;\n      word-break: keep-all;\n    }\n\n    .example {\n      display: inline-flex;\n      gap: 10px;\n      align-items: center;\n      margin-top: 20px;\n      padding: 11px 15px;\n      color: #7c5036;\n      background: var(--peach);\n      border-radius: 13px;\n      font-size: 0.9rem;\n      font-weight: 700;\n      transform: rotate(-0.5deg);\n    }\n\n    .example-icon {\n      font-size: 1.45rem;\n    }\n\n    .role-grid,\n    .purpose-grid {\n      display: grid;\n      gap: 12px;\n    }\n\n    .role-grid {\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n    }\n\n    .purpose-grid {\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      margin-top: 18px;\n    }\n\n    .info-card {\n      min-height: 128px;\n      padding: 20px;\n      background: var(--blue-soft);\n      border-radius: 15px;\n    }\n\n    .info-card:nth-child(even) {\n      background: var(--mint);\n    }\n\n    .info-card strong {\n      display: block;\n      margin-bottom: 7px;\n      color: var(--ink);\n      font-size: 1rem;\n    }\n\n    .info-card span {\n      display: block;\n      color: var(--text);\n      font-size: 0.88rem;\n      word-break: keep-all;\n    }\n\n    .purpose-card {\n      padding: 18px;\n      border: 1px solid var(--line);\n      border-top: 4px solid var(--blue);\n      border-radius: 4px 4px 12px 12px;\n    }\n\n    .purpose-card strong {\n      display: block;\n      margin-bottom: 6px;\n      color: var(--ink);\n      font-size: 0.94rem;\n    }\n\n    .purpose-card span {\n      display: block;\n      color: var(--muted);\n      font-size: 0.82rem;\n      word-break: keep-all;\n    }\n\n    .trait-list {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 10px;\n      margin-bottom: 18px;\n    }\n\n    .trait {\n      padding: 7px 12px;\n      color: var(--blue);\n      background: var(--blue-soft);\n      border-radius: 999px;\n      font-size: 0.88rem;\n      font-weight: 800;\n    }\n\n    .interest-layout {\n      display: grid;\n      grid-template-columns: auto 1fr;\n      gap: 24px;\n      align-items: center;\n    }\n\n    .interest-icons {\n      width: 112px;\n      height: 112px;\n      display: grid;\n      place-items: center;\n      background: var(--mint);\n      border-radius: 50%;\n      font-size: 2.25rem;\n      white-space: nowrap;\n    }\n\n    footer {\n      padding: 28px;\n      color: var(--muted);\n      text-align: center;\n      background: color-mix(in srgb, var(--paper) 94%, var(--page));\n      border-top: 1px solid var(--line);\n      font-size: 0.82rem;\n    }\n\n    @media (max-width: 760px) {\n      .page {\n        width: 100%;\n        margin: 0;\n        box-shadow: none;\n      }\n\n      .theme-toggle {\n        position: fixed;\n        top: 14px;\n        right: 14px;\n        background: color-mix(in srgb, var(--paper) 92%, transparent);\n        backdrop-filter: blur(8px);\n      }\n\n      .hero {\n        min-height: auto;\n        grid-template-columns: 1fr;\n        gap: 32px;\n        padding: 40px 24px;\n      }\n\n      .portrait {\n        width: 190px;\n        justify-self: start;\n        grid-row: 1;\n      }\n\n      .hero-copy {\n        grid-row: 2;\n      }\n\n      .section {\n        grid-template-columns: 1fr;\n        gap: 20px;\n      }\n\n      .role-grid,\n      .purpose-grid {\n        grid-template-columns: 1fr;\n      }\n\n      .info-card {\n        min-height: auto;\n      }\n    }\n\n    @media (max-width: 460px) {\n      .content {\n        padding: 0 22px;\n      }\n\n      .interest-layout {\n        grid-template-columns: 1fr;\n      }\n\n      .interest-icons {\n        width: 96px;\n        height: 96px;\n      }\n    }\n  </style>\n</head>\n<body>\n  <main class=\"page\">\n    <button class=\"theme-toggle\" type=\"button\" aria-label=\"다크모드 전환\" aria-pressed=\"false\">\n      <span class=\"theme-icon\" aria-hidden=\"true\">◐</span>\n      <span class=\"theme-label\">다크모드</span>\n    </button>\n\n    <header class=\"hero\">\n      <div class=\"hero-copy\">\n        <p class=\"hero-label\">PERSONAL PROFILE</p>\n        <h1>이성호</h1>\n        <p class=\"name-en\">LEE SUNG HO</p>\n        <p class=\"job\">임베디드 엔지니어 · 전자제품 개발자</p>\n        <p class=\"role\">스타트업 개발팀장</p>\n        <p class=\"hero-statement\">생활 속 아이디어를 실제로 움직이는 제품으로 만듭니다.</p>\n      </div>\n\n      <div class=\"portrait\" aria-label=\"이성호 프로필 그래픽\">\n        <span class=\"initials\">SH</span>\n        <span class=\"plant\" aria-hidden=\"true\">🪴</span>\n      </div>\n    </header>\n\n    <div class=\"content\">\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\">01 · WHO I AM</span>\n          <h2>어떤 사람인가</h2>\n        </div>\n        <div class=\"section-body\">\n          <p class=\"lead\">문제가 생기면 직접 확인하고, 원인을 찾을 때까지 차근차근 살펴봅니다.</p>\n          <p class=\"sub-copy\">복잡한 문제는 작은 단위로 나누고 실제 사용 환경에서도 안정적으로 쓸 수 있는 결과를 중요하게 생각합니다.</p>\n          <div class=\"example\"><span class=\"example-icon\" aria-hidden=\"true\">🪴</span>목마르면 표정이 바뀌는 화분 같은 아이디어를 좋아합니다.</div>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\">02 · WHAT I DO</span>\n          <h2>현재 하는 일</h2>\n        </div>\n        <div class=\"section-body role-grid\">\n          <article class=\"info-card\">\n            <strong>아이디어 구체화</strong>\n            <span>생활 속 생각을 실제로 개발할 수 있는 제품의 모습으로 정리합니다.</span>\n          </article>\n          <article class=\"info-card\">\n            <strong>팀과 문제 해결</strong>\n            <span>개발 과정에서 생기는 문제를 팀원들과 확인하고 함께 해결합니다.</span>\n          </article>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\">03 · WHY I’M HERE</span>\n          <h2>교육에 참여한 이유</h2>\n        </div>\n        <div class=\"section-body\">\n          <p class=\"lead\">바이브코딩을 실제 업무에 활용할 방법을 직접 확인해 보고 싶습니다.</p>\n          <div class=\"purpose-grid\">\n            <div class=\"purpose-card\"><strong>테스트용 앱</strong><span>제품 기능과 아이디어 확인</span></div>\n            <div class=\"purpose-card\"><strong>업무 도구</strong><span>반복적인 개발 업무 줄이기</span></div>\n            <div class=\"purpose-card\"><strong>소개 자료</strong><span>회사와 제품을 쉽게 설명하기</span></div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\">04 · HOW I THINK</span>\n          <h2>일하는 방식</h2>\n        </div>\n        <div class=\"section-body\">\n          <div class=\"trait-list\" aria-label=\"나를 표현하는 키워드\">\n            <span class=\"trait\">호기심</span>\n            <span class=\"trait\">끈기</span>\n            <span class=\"trait\">현실적인 문제 해결</span>\n          </div>\n          <p class=\"lead\">넘겨짚기보다 직접 확인하고, 임시방편보다 실제로 계속 사용할 수 있는 방법을 찾습니다.</p>\n        </div>\n      </section>\n\n      <section class=\"section\">\n        <div>\n          <span class=\"section-index\">05 · OUTSIDE WORK</span>\n          <h2>좋아하는 시간</h2>\n        </div>\n        <div class=\"section-body interest-layout\">\n          <div class=\"interest-icons\" aria-hidden=\"true\">🚗 🎵</div>\n          <p class=\"lead\">그날의 기분에 따라 다양한 음악을 들으며 운전하고, 생각을 정리하는 시간을 좋아합니다.</p>\n        </div>\n      </section>\n    </div>\n\n    <footer>교육에서 잘 부탁드립니다.</footer>\n  </main>\n  <script>\n    (() => {\n      const root = document.documentElement;\n      const button = document.querySelector(\".theme-toggle\");\n      const label = document.querySelector(\".theme-label\");\n      const applyTheme = (theme) => {\n        const isDark = theme === \"dark\";\n        root.dataset.theme = theme;\n        button.setAttribute(\"aria-pressed\", String(isDark));\n        label.textContent = isDark ? \"라이트모드\" : \"다크모드\";\n      };\n\n      applyTheme(root.dataset.theme);\n\n      button.addEventListener(\"click\", () => {\n        const nextTheme = root.dataset.theme === \"dark\" ? \"light\" : \"dark\";\n        localStorage.setItem(\"profile-theme\", nextTheme);\n        applyTheme(nextTheme);\n      });\n    })();\n  </script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not Found", { status: 404 });
    }

    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "public, max-age=300"
      }
    });
  }
};
